/* Классовые инструменты Classic, которых не было в наборах (владелец, 27 ноября; аудит классов): действуют весь бой, по собственному уровню, не в учебном наборе.
   Защита паладина — «Праведное неистовство» (Classic 16: угроза ×1.6) и ответный урон Светом атакующим (как Аура воздаяния);
   Свет паладина — «Печать праведности» (Classic 1: удары с шансом добавляют урон Светом); Тайная магия — «Мана-щит» (Classic 20: щит в начале боя). */
st.heroes.forEach(function (h) {
  if (h.neutralTraining || h.dummy) return;
  const t = CLASS_TOOLS[h.cls + ':' + h.spec]; if (!t || h.level < t.level) return;
  if (t.rf) h.effects.push({ kind: 'rf', turns: 999, src: h.id, name: 'Праведное неистовство', icon: '🔥' });
  if (t.reflect) h.effects.push({ kind: 'reflect', amt: t.reflect, turns: 999, src: h.id, name: 'Аура воздаяния', icon: '✨' });
  if (t.seal) h.effects.push({ kind: 'seal', turns: 999, src: h.id, name: 'Печать праведности', icon: '⚖️' });
  if (t.shield) h.effects.push({ kind: 'shield', amt: Math.round(h.maxHp * t.shield), turns: 999, src: h.id, name: 'Мана-щит', icon: '🔷' });
});
if (opts.experiment || opts.party.some(function (p) { return p.proto; })) protoSetupAll(st, opts);
